-- Completes source import from Monthly Progress Report May 2025.xlsx.
-- Adds April HSE comparison data plus May Security, Environment, Ecopit, CSR and Grievances.
-- Run after migrations 001–004.

insert into public.reporting_periods (period_date) values ('2025-04-01') on conflict (period_date) do nothing;

-- Pre-April baseline, so Apr + May values reproduce the workbook's May inception-to-date values.
update public.hse_incident_types set inception_baseline = case code
 when 'BANKERS_LTI' then 20 when 'CONTRACTOR_LTI' then 62 when 'RESTRICTED_WORK_CASE' then 29 when 'PERSONNEL_INJURY_FA' then 158 when 'PERSONNEL_INJURY_MT' then 65
 when 'PROPERTY_DAMAGE' then 229 when 'NEAR_MISS' then 331 when 'ENVIRONMENTAL' then 734 when 'SECURITY' then 4372 when 'MOTOR_VEHICLE_ACCIDENTS' then 502
 when 'FATALITY' then 1 when 'FIRES' then 60 when 'NON_TABULATED' then 30 else inception_baseline end;
with source(code,incident_count) as (values ('BANKERS_LTI',0),('CONTRACTOR_LTI',0),('RESTRICTED_WORK_CASE',0),('PERSONNEL_INJURY_FA',0),('PERSONNEL_INJURY_MT',0),('PROPERTY_DAMAGE',1),('NEAR_MISS',0),('ENVIRONMENTAL',3),('SECURITY',0),('MOTOR_VEHICLE_ACCIDENTS',1),('FATALITY',0),('FIRES',0),('NON_TABULATED',0))
insert into public.hse_monthly_incidents(reporting_period_id,incident_type_id,incident_count) select p.id,t.id,s.incident_count from source s join public.hse_incident_types t on t.code=s.code cross join public.reporting_periods p where p.period_date='2025-04-01' on conflict(reporting_period_id,incident_type_id) do update set incident_count=excluded.incident_count,updated_at=now();
insert into public.hse_exposure_hours(reporting_period_id,bankers_hours,contractor_hours) select id,75020,138752 from public.reporting_periods where period_date='2025-04-01' on conflict(reporting_period_id) do update set bankers_hours=excluded.bankers_hours,contractor_hours=excluded.contractor_hours,updated_at=now();

-- Security Operations, May 2025.
insert into public.security_monthly_reports(reporting_period_id,security_incident_count,mobile_patrol_spot_checks,geofence_dispatches,gps_operator_spot_checks,storage_yard_spot_checks,inventory_checks,security_investigations,static_sites,operations_support,security_incidents,incidents_high_importance)
select id,1,715,92,1204,0,0,1,41,
 jsonb_build_object('html','<p>There were 01 security incident this month.</p>'),
 jsonb_build_object('html','<ul><li>715 documented spot checks were carried out by the security mobile patrols on contractor tanker trucks. In addition there were numerous spot checks carried out on various types of contractor’s vehicles.</li><li>The six Mobile Patrols were dispatched 92 times this month for lease geo fence breaches.</li><li>1204 documented spot checks were conducted by the GPS operators.</li><li>0 documentation spot check was conducted at the New Storage Yard.</li><li>0 BPAL NSY Inventory checks were conducted this month.</li><li>1 security investigations were conducted this month.</li><li>The guard force provided security at 41 static sites.</li></ul>'),
 jsonb_build_object('html','<p>None</p>') from public.reporting_periods where period_date='2025-05-01'
on conflict(reporting_period_id) do update set security_incident_count=excluded.security_incident_count,mobile_patrol_spot_checks=excluded.mobile_patrol_spot_checks,geofence_dispatches=excluded.geofence_dispatches,gps_operator_spot_checks=excluded.gps_operator_spot_checks,storage_yard_spot_checks=excluded.storage_yard_spot_checks,inventory_checks=excluded.inventory_checks,security_investigations=excluded.security_investigations,static_sites=excluded.static_sites,operations_support=excluded.operations_support,security_incidents=excluded.security_incidents,incidents_high_importance=excluded.incidents_high_importance,updated_at=now();

-- Environment, May 2025. Workbook Ecopit figures label their source date as April; that provenance is retained in the narrative.
insert into public.environment_monthly_reports(reporting_period_id,environmental_incident_count,operations_support,incidents_breakdown,environmental_incidents,monitoring_program)
select id,0,
jsonb_build_object('html','<ul><li>Ongoing site audits and inspections, including water, noise and air monitoring and sampling, environmental compliance audits, lease and well site inspections.</li><li>Monitoring of fluid levels in ecopits and wet mud facility.</li><li>The Ecology pits receiving waste this month were Ecopit 3 and 8.</li><li>The value for all other pits was zero.</li><li>Ongoing monitoring and response to environmental incidents, spills and community grievances.</li><li>Supervision and management of ongoing regulatory requests for information.</li><li>Communication with the National Environmental Agency for permitting matters.</li></ul>'),jsonb_build_object('html','<p>No incident breakdown was recorded in the workbook section.</p>'),jsonb_build_object('html','<p>There were 00 reportable environmental incident this month.</p>'),jsonb_build_object('html','<ul><li>Environmental monitoring programme completed.</li><li>Continued work for the 3, 6 monthly and yearly reports to the regulators.</li><li>Completed monitoring programme with third parties.</li></ul>') from public.reporting_periods where period_date='2025-05-01'
on conflict(reporting_period_id) do update set environmental_incident_count=excluded.environmental_incident_count,operations_support=excluded.operations_support,incidents_breakdown=excluded.incidents_breakdown,environmental_incidents=excluded.environmental_incidents,monitoring_program=excluded.monitoring_program,updated_at=now();
with source(ecopit,waste_type,quantity_m3) as (values ('Ecopit 3','CONTAMINATED_GRAVEL_SOIL',0::numeric),('Ecopit 3','EMULSION',516.26),('Ecopit 3','WATER',0),('Ecopit 3','DRILLING_CUTTINGS',0),('Ecopit 3','DRILLING_MUD',0),('Ecopit 3','PRODUCED_SAND',0),('Ecopit 3','SOLIDS',0),('Ecopit 3','SLUDGE',0),('Ecopit 3','BOTTOM_TANK_SLUDGE',124.27),('Ecopit 8','CONTAMINATED_GRAVEL_SOIL',0),('Ecopit 8','EMULSION',1655.94),('Ecopit 8','WATER',0),('Ecopit 8','DRILLING_CUTTINGS',0),('Ecopit 8','DRILLING_MUD',0),('Ecopit 8','PRODUCED_SAND',114),('Ecopit 8','SOLIDS',0),('Ecopit 8','SLUDGE',586.82),('Ecopit 8','BOTTOM_TANK_SLUDGE',1304.43))
insert into public.environment_ecopit_monthly_values(reporting_period_id,ecopit,waste_type,quantity_m3) select p.id,s.ecopit,s.waste_type,s.quantity_m3 from source s cross join public.reporting_periods p where p.period_date='2025-05-01' on conflict(reporting_period_id,ecopit,waste_type) do update set quantity_m3=excluded.quantity_m3,updated_at=now();

-- CSR, May 2025.
insert into public.csr_monthly_reports(reporting_period_id,social_infrastructure_projects,other_activities) select id,jsonb_build_object('html','<p>Community Investment Projects: Fier municipality project started implementation; Roskovec municipality working to select contractor and submit its documentation.</p>'),jsonb_build_object('html','<ul><li>Conducting Social Risk Assessment for the new wells to be drilled as part of Drilling schedule for 2025.</li><li>Visiting drilling site locations and providing social inputs.</li><li>Received a request from Fier Hospital to support with medical equipment. Request approved internally and equipment to be delivered in June 2025.</li><li>Regular communication with local authorities and residents to address concerns related to operations at pad M37a.</li><li>Received a request from Mbrostar Administrative Unit to support with improvement of agriculture roads in the area. Cost estimate to be prepared prior decision making.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>') from public.reporting_periods where period_date='2025-05-01' on conflict(reporting_period_id) do update set social_infrastructure_projects=excluded.social_infrastructure_projects,other_activities=excluded.other_activities,updated_at=now();
insert into public.csr_grievances(reporting_period_id,grievance_date,project_activity,category,status,validity) select p.id,s.grievance_date,s.project_activity,s.category,s.status,s.validity::public.grievance_validity from (values ('2025-05-06'::date,'Drilling','Noise','Closed','VALID'),('2025-05-23'::date,'Operations','Drainage cleaning/Maintenance','Open','PENDING')) s(grievance_date,project_activity,category,status,validity) cross join public.reporting_periods p where p.period_date='2025-05-01' and not exists(select 1 from public.csr_grievances g where g.reporting_period_id=p.id and g.grievance_date=s.grievance_date and g.project_activity=s.project_activity);
